css:
.wrap{max-width:46rem;margin:0 auto;padding:1.4rem 1rem 3rem;font:16px/1.7 system-ui,sans-serif;color:#221e18}
h1{font-size:1.5rem;margin:0 0 1rem}
h2{font-size:1.05rem;margin:1.6rem 0 .5rem}
.diagram{width:100%;height:auto;display:block}
.box{fill:#f3ecdb;stroke:#c9b88c;stroke-width:1.2}
.lbl{font:12px system-ui,sans-serif;fill:#4a4132}
.edge{stroke:#7a6a4a;stroke-width:1.4}
canvas{width:100%;height:auto}
.note{font-size:.85rem;color:#6d6459}
.row{display:grid;gap:.35rem;font-size:.9rem}
output{display:block;margin-top:.4rem;font-variant-numeric:tabular-nums}

javascript:
import Chart from 'chart.js';
import katex from 'katex';

new Chart(document.getElementById('chart'), {
  type: 'bar',
  data: { labels: ['甲篇', '乙篇'], datasets: [{ label: '要点数（示例）', data: [4, 7] }] },
  options: { responsive: true, animation: false, plugins: { legend: { display: false } } },
});

katex.render('\\mathrm{SE} = s / \\sqrt{n}', document.getElementById('math'), {
  displayMode: true, throwOnError: false, trust: false,
});

const slider = document.getElementById('n');
const out = document.getElementById('out');
function refresh() {
  const n = Number(slider.value);
  out.textContent = 'n=' + n + '，示例标准误约为 ' + (1 / Math.sqrt(n)).toFixed(3) + '（示例数据，非材料结果）';
}
slider.addEventListener('input', refresh);
refresh();
